/**
 * storage.js - IndexedDB storage engine with localStorage fallback and version migration.
 */
const DB_NAME = 'NexusTitanDB';
const DB_VERSION = 1;
const STORE_NAME = 'titan_store';

class StorageEngine {
  constructor() {
    this.db = null;
    this.isIndexedDBSupported = typeof indexedDB !== 'undefined';
  }

  async init() {
    if (!this.isIndexedDBSupported) return Promise.resolve();
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);
      request.onupgradeneeded = (event) => {
        const db = event.target.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME);
        }
      };
      request.onsuccess = (event) => {
        this.db = event.target.result;
        resolve(this.db);
      };
      request.onerror = (event) => {
        console.warn('IndexedDB failed, falling back to localStorage', event.target.error);
        this.isIndexedDBSupported = false;
        resolve(null);
      };
    });
  }

  async get(key) {
    if (this.isIndexedDBSupported && this.db) {
      return new Promise((resolve, reject) => {
        try {
          const transaction = this.db.transaction(STORE_NAME, 'readonly');
          const store = transaction.objectStore(STORE_NAME);
          const request = store.get(key);
          request.onsuccess = () => resolve(request.result !== undefined ? request.result : null);
          request.onerror = () => reject(request.error);
        } catch (e) {
          resolve(this._getFromLocalStorage(key));
        }
      });
    }
    return this._getFromLocalStorage(key);
  }

  async set(key, value) {
    if (this.isIndexedDBSupported && this.db) {
      return new Promise((resolve, reject) => {
        try {
          const transaction = this.db.transaction(STORE_NAME, 'readwrite');
          const store = transaction.objectStore(STORE_NAME);
          const request = store.put(value, key);
          request.onsuccess = () => resolve(true);
          request.onerror = () => reject(request.error);
        } catch (e) {
          resolve(this._setToLocalStorage(key, value));
        }
      });
    }
    return this._setToLocalStorage(key, value);
  }

  async remove(key) {
    if (this.isIndexedDBSupported && this.db) {
      return new Promise((resolve, reject) => {
        try {
          const transaction = this.db.transaction(STORE_NAME, 'readwrite');
          const store = transaction.objectStore(STORE_NAME);
          const request = store.delete(key);
          request.onsuccess = () => resolve(true);
          request.onerror = () => reject(request.error);
        } catch (e) {
          resolve(this._removeFromLocalStorage(key));
        }
      });
    }
    return this._removeFromLocalStorage(key);
  }

  _getFromLocalStorage(key) {
    try {
      const item = localStorage.getItem(key);
      return item ? JSON.parse(item) : null;
    } catch (e) {
      console.error('LocalStorage read error', e);
      return null;
    }
  }

  _setToLocalStorage(key, value) {
    try {
      localStorage.setItem(key, JSON.stringify(value));
      return true;
    } catch (e) {
      console.error('LocalStorage write error', e);
      return false;
    }
  }

  _removeFromLocalStorage(key) {
    try {
      localStorage.removeItem(key);
      return true;
    } catch (e) {
      console.error('LocalStorage remove error', e);
      return false;
    }
  }
}

window.storageEngine = new StorageEngine();

/**
 * state.js - Central State Management, PubSub, and Undo/Redo history stack.
 */
class StateManager {
  constructor() {
    this.state = {
      tasks: [],
      projects: [],
      settings: {
        theme: 'system',
        accent: 'blue',
        compactMode: false,
        animations: true,
        reducedMotion: false,
        defaultPriority: 'medium',
        defaultStatus: 'todo',
        itemsPerPage: 25,
        confirmDelete: true,
        notificationsEnabled: true
      },
      activityLogs: [],
      notifications: []
    };
    this.listeners = [];
    this.history = [];
    this.redoStack = [];
    this.maxHistory = 50;
  }

  subscribe(listener) {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  notify() {
    this.listeners.forEach(listener => listener(this.state));
  }

  async loadState() {
    const tasks = await window.storageEngine.get('nexus_tasks') || [];
    const projects = await window.storageEngine.get('nexus_projects') || [];
    const settings = await window.storageEngine.get('nexus_settings') || this.state.settings;
    const activityLogs = await window.storageEngine.get('nexus_activity') || [];
    const notifications = await window.storageEngine.get('nexus_notifications') || [];

    this.state = { tasks, projects, settings, activityLogs, notifications };
    this.notify();
  }

  async persist() {
    await window.storageEngine.set('nexus_tasks', this.state.tasks);
    await window.storageEngine.set('nexus_projects', this.state.projects);
    await window.storageEngine.set('nexus_settings', this.state.settings);
    await window.storageEngine.set('nexus_activity', this.state.activityLogs);
    await window.storageEngine.set('nexus_notifications', this.state.notifications);
  }

  pushHistory() {
    const snapshot = JSON.parse(JSON.stringify({
      tasks: this.state.tasks,
      projects: this.state.projects,
      settings: this.state.settings
    }));
    this.history.push(snapshot);
    if (this.history.length > this.maxHistory) {
      this.history.shift();
    }
    this.redoStack = [];
  }

  undo() {
    if (this.history.length === 0) return false;
    const currentSnapshot = JSON.parse(JSON.stringify({
      tasks: this.state.tasks,
      projects: this.state.projects,
      settings: this.state.settings
    }));
    this.redoStack.push(currentSnapshot);
    const previous = this.history.pop();
    this.state.tasks = previous.tasks;
    this.state.projects = previous.projects;
    this.state.settings = previous.settings;
    this.persist();
    this.notify();
    this.logActivity('Undo performed');
    return true;
  }

  redo() {
    if (this.redoStack.length === 0) return false;
    const currentSnapshot = JSON.parse(JSON.stringify({
      tasks: this.state.tasks,
      projects: this.state.projects,
      settings: this.state.settings
    }));
    this.history.push(currentSnapshot);
    const next = this.redoStack.pop();
    this.state.tasks = next.tasks;
    this.state.projects = next.projects;
    this.state.settings = next.settings;
    this.persist();
    this.notify();
    this.logActivity('Redo performed');
    return true;
  }

  logActivity(action) {
    const log = {
      id: 'act_' + Math.random().toString(36).substr(2, 9),
      action,
      timestamp: new Date().toISOString()
    };
    this.state.activityLogs.unshift(log);
    if (this.state.activityLogs.length > 200) this.state.activityLogs.pop();
    window.storageEngine.set('nexus_activity', this.state.activityLogs);
  }

  addNotification(title, message, type = 'info') {
    if (!this.state.settings.notificationsEnabled) return;
    const notif = {
      id: 'notif_' + Math.random().toString(36).substr(2, 9),
      title,
      message,
      type,
      read: false,
      timestamp: new Date().toISOString()
    };
    this.state.notifications.unshift(notif);
    window.storageEngine.set('nexus_notifications', this.state.notifications);
    this.notify();
    if (window.showToast) window.showToast(message, type);
  }
}

window.stateManager = new StateManager();

/**
 * tasks.js - Task Engine handling CRUD, validation, subtasks, tags, and time tracking.
 */
class TaskEngine {
  constructor(stateManager) {
    this.stateManager = stateManager;
  }

  validateTask(taskData, existingTasks = []) {
    if (!taskData.title || typeof taskData.title !== 'string' || taskData.title.trim() === '') {
      throw new Error('Task title cannot be empty.');
    }
    if (taskData.id && existingTasks.some(t => t.id === taskData.id && t !== taskData._original)) {
      throw new Error('Task ID must be unique.');
    }
    if (taskData.dependencies && taskData.id && taskData.dependencies.includes(taskData.id)) {
      throw new Error('Task cannot depend on itself.');
    }
    // Cycle check
    if (taskData.dependencies && taskData.dependencies.length > 0 && taskData.id) {
      for (const depId of taskData.dependencies) {
        if (this._hasDependencyCycle(depId, taskData.id, existingTasks)) {
          throw new Error('Dependency cycle detected.');
        }
      }
    }
    return true;
  }

  _hasDependencyCycle(currentId, targetId, tasks) {
    const task = tasks.find(t => t.id === currentId);
    if (!task || !task.dependencies) return false;
    if (task.dependencies.includes(targetId)) return true;
    return task.dependencies.some(depId => this._hasDependencyCycle(depId, targetId, tasks));
  }

  createTask(data) {
    this.stateManager.pushHistory();
    const newTask = {
      id: 'task_' + Math.random().toString(36).substr(2, 9),
      title: data.title.trim(),
      description: data.description || '',
      status: data.status || this.stateManager.state.settings.defaultStatus,
      priority: data.priority || this.stateManager.state.settings.defaultPriority,
      projectId: data.projectId || '',
      tags: data.tags || [],
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      dueDate: data.dueDate || null,
      completedAt: data.status === 'done' ? new Date().toISOString() : null,
      estimatedMinutes: Number(data.estimatedMinutes) || 0,
      actualMinutes: Number(data.actualMinutes) || 0,
      subtasks: data.subtasks || [],
      dependencies: data.dependencies || [],
      notes: data.notes || ''
    };

    this.validateTask(newTask, this.stateManager.state.tasks);
    this.stateManager.state.tasks.push(newTask);
    this.stateManager.persist();
    this.stateManager.logActivity(`Created task: ${newTask.title}`);
    this.stateManager.addNotification('Task Created', `Successfully created task "${newTask.title}"`, 'success');
    this.stateManager.notify();
    return newTask;
  }

  updateTask(id, updates) {
    this.stateManager.pushHistory();
    const tasks = this.stateManager.state.tasks;
    const index = tasks.findIndex(t => t.id === id);
    if (index === -1) throw new Error('Task not found.');

    const updated = {
      ...tasks[index],
      ...updates,
      updatedAt: new Date().toISOString()
    };
    if (updates.status === 'done' && tasks[index].status !== 'done') {
      updated.completedAt = new Date().toISOString();
    } else if (updates.status && updates.status !== 'done') {
      updated.completedAt = null;
    }

    updated._original = tasks[index];
    this.validateTask(updated, tasks);
    delete updated._original;

    tasks[index] = updated;
    this.stateManager.persist();
    this.stateManager.logActivity(`Updated task: ${updated.title}`);
    this.stateManager.notify();
    return updated;
  }

  deleteTask(id) {
    this.stateManager.pushHistory();
    const tasks = this.stateManager.state.tasks;
    const index = tasks.findIndex(t => t.id === id);
    if (index === -1) throw new Error('Task not found.');
    const removed = tasks.splice(index, 1)[0];
    this.stateManager.persist();
    this.stateManager.logActivity(`Deleted task: ${removed.title}`);
    this.stateManager.addNotification('Task Deleted', `Deleted task "${removed.title}"`, 'info');
    this.stateManager.notify();
    return removed;
  }

  duplicateTask(id) {
    const tasks = this.stateManager.state.tasks;
    const task = tasks.find(t => t.id === id);
    if (!task) return null;
    return this.createTask({
      ...task,
      title: `${task.title} (Copy)`,
      id: undefined
    });
  }

  completeTask(id, completed = true) {
    return this.updateTask(id, {
      status: completed ? 'done' : 'todo'
    });
  }
}

window.taskEngine = new TaskEngine(window.stateManager);

/**
 * projects.js - Project Management handling CRUD, archive, restore, and statistics.
 */
class ProjectEngine {
  constructor(stateManager) {
    this.stateManager = stateManager;
  }

  createProject(data) {
    if (!data.name || data.name.trim() === '') {
      throw new Error('Project name cannot be empty.');
    }
    this.stateManager.pushHistory();
    const newProj = {
      id: 'proj_' + Math.random().toString(36).substr(2, 9),
      name: data.name.trim(),
      description: data.description || '',
      color: data.color || '#3b82f6',
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      archived: false
    };
    this.stateManager.state.projects.push(newProj);
    this.stateManager.persist();
    this.stateManager.logActivity(`Created project: ${newProj.name}`);
    this.stateManager.addNotification('Project Created', `Created project "${newProj.name}"`, 'success');
    this.stateManager.notify();
    return newProj;
  }

  updateProject(id, updates) {
    this.stateManager.pushHistory();
    const projects = this.stateManager.state.projects;
    const index = projects.findIndex(p => p.id === id);
    if (index === -1) throw new Error('Project not found.');

    projects[index] = {
      ...projects[index],
      ...updates,
      updatedAt: new Date().toISOString()
    };
    this.stateManager.persist();
    this.stateManager.logActivity(`Updated project: ${projects[index].name}`);
    this.stateManager.notify();
    return projects[index];
  }

  deleteProject(id, force = false) {
    const tasks = this.stateManager.state.tasks;
    const hasTasks = tasks.some(t => t.projectId === id);
    if (hasTasks && !force) {
      throw new Error('Project contains tasks. Confirm deletion or move tasks first.');
    }

    this.stateManager.pushHistory();
    const projects = this.stateManager.state.projects;
    const index = projects.findIndex(p => p.id === id);
    if (index === -1) throw new Error('Project not found.');
    const removed = projects.splice(index, 1)[0];

    // Optionally unassign tasks
    tasks.forEach(t => {
      if (t.projectId === id) t.projectId = '';
    });

    this.stateManager.persist();
    this.stateManager.logActivity(`Deleted project: ${removed.name}`);
    this.stateManager.addNotification('Project Deleted', `Deleted project "${removed.name}"`, 'info');
    this.stateManager.notify();
    return removed;
  }

  archiveProject(id, archived = true) {
    return this.updateProject(id, { archived });
  }

  getProjectStats(projectId) {
    const tasks = this.stateManager.state.tasks.filter(t => t.projectId === projectId);
    const total = tasks.length;
    const completed = tasks.filter(t => t.status === 'done').length;
    const rate = total > 0 ? Math.round((completed / total) * 100) : 0;
    return { total, completed, rate };
  }
}

window.projectEngine = new ProjectEngine(window.stateManager);

/**
 * calendar.js - Calendar view computations and date management.
 */
class CalendarEngine {
  constructor(stateManager) {
    this.stateManager = stateManager;
    this.currentDate = new Date();
  }

  getTasksForDate(dateString) {
    return this.stateManager.state.tasks.filter(t => {
      if (!t.dueDate) return false;
      return t.dueDate.startsWith(dateString);
    });
  }

  getMonthDays(year, month) {
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const days = [];

    // Padding for start of week
    const startDayOfWeek = firstDay.getDay();
    for (let i = startDayOfWeek - 1; i >= 0; i--) {
      const d = new Date(year, month, -i);
      days.push({ date: d, isCurrentMonth: false });
    }

    // Current month days
    for (let i = 1; i <= lastDay.getDate(); i++) {
      const d = new Date(year, month, i);
      days.push({ date: d, isCurrentMonth: true });
    }

    // Padding for end of week
    const remainingDays = 42 - days.length;
    for (let i = 1; i <= remainingDays; i++) {
      const d = new Date(year, month + 1, i);
      days.push({ date: d, isCurrentMonth: false });
    }

    return days;
  }
}

window.calendarEngine = new CalendarEngine(window.stateManager);

/**
 * analytics.js - Analytics computation engine and SVG chart generator.
 */
class AnalyticsEngine {
  constructor(stateManager) {
    this.stateManager = stateManager;
  }

  computeMetrics() {
    const tasks = this.stateManager.state.tasks;
    const total = tasks.length;
    const completed = tasks.filter(t => t.status === 'done').length;
    const todo = tasks.filter(t => t.status === 'todo').length;
    const inProgress = tasks.filter(t => t.status === 'in-progress').length;
    const blocked = tasks.filter(t => t.status === 'blocked').length;
    const review = tasks.filter(t => t.status === 'review').length;

    const now = new Date();
    const overdue = tasks.filter(t => t.dueDate && new Date(t.dueDate) < now && t.status !== 'done').length;
    const highPriority = tasks.filter(t => t.priority === 'high' || t.priority === 'urgent').length;
    const completionRate = total > 0 ? Math.round((completed / total) * 100) : 0;
    const overdueRate = total > 0 ? Math.round((overdue / total) * 100) : 0;

    return {
      total,
      completed,
      todo,
      inProgress,
      blocked,
      review,
      overdue,
      highPriority,
      completionRate,
      overdueRate
    };
  }

  renderBarChart(containerId, data, labels) {
    const container = document.getElementById(containerId);
    if (!container) return;
    const max = Math.max(...data, 1);
    let html = '<div class="chart-bars">';
    data.forEach((val, i) => {
      const height = Math.round((val / max) * 100);
      html += `<div class="chart-bar-col" title="${labels[i]}: ${val}">
                 <div class="chart-bar" style="height: ${height}%"></div>
                 <span class="chart-label">${labels[i]}</span>
               </div>`;
    });
    html += '</div>';
    container.innerHTML = html;
  }
}

window.analyticsEngine = new AnalyticsEngine(window.stateManager);

/**
 * search.js - Advanced search engine supporting syntax like status:done priority:high.
 */
class SearchEngine {
  constructor(stateManager) {
    this.stateManager = stateManager;
  }

  search(query) {
    const tasks = this.stateManager.state.tasks;
    if (!query || query.trim() === '') return tasks;

    const tokens = query.toLowerCase().split(/\s+/);
    const filters = {};
    const textTerms = [];

    tokens.forEach(token => {
      if (token.includes(':')) {
        const [key, value] = token.split(':');
        filters[key] = value;
      } else {
        textTerms.push(token);
      }
    });

    return tasks.filter(task => {
      // Check filters
      if (filters.status && task.status !== filters.status) return false;
      if (filters.priority && task.priority !== filters.priority) return false;
      if (filters.project && task.projectId !== filters.project) return false;
      if (filters.tag && (!task.tags || !task.tags.includes(filters.tag))) return false;
      if (filters.overdue === 'true') {
        if (!task.dueDate || new Date(task.dueDate) >= new Date() || task.status === 'done') return false;
      }

      // Check text terms
      if (textTerms.length > 0) {
        const combinedText = `${task.title} ${task.description} ${task.notes}`.toLowerCase();
        const matchesAll = textTerms.every(term => combinedText.includes(term));
        if (!matchesAll) return false;
      }

      return true;
    });
  }
}

window.searchEngine = new SearchEngine(window.stateManager);

/**
 * commands.js - Command Palette (Ctrl+K) handler and shortcuts.
 */
class CommandPalette {
  constructor(stateManager) {
    this.stateManager = stateManager;
    this.isOpen = false;
  }

  toggle() {
    this.isOpen = !this.isOpen;
    const modal = document.getElementById('command-palette-modal');
    if (modal) {
      modal.style.display = this.isOpen ? 'flex' : 'none';
      if (this.isOpen) {
        const input = document.getElementById('command-input');
        if (input) input.focus();
      }
    }
  }

  getCommands() {
    return [
      { id: 'create-task', title: 'Create New Task', action: () => window.uiManager.openTaskModal() },
      { id: 'create-project', title: 'Create New Project', action: () => window.uiManager.openProjectModal() },
      { id: 'view-dashboard', title: 'Open Dashboard', action: () => window.uiManager.switchView('dashboard') },
      { id: 'view-tasks', title: 'Open Tasks List', action: () => window.uiManager.switchView('tasks') },
      { id: 'view-kanban', title: 'Open Kanban Board', action: () => window.uiManager.switchView('kanban') },
      { id: 'view-calendar', title: 'Open Calendar', action: () => window.uiManager.switchView('calendar') },
      { id: 'view-analytics', title: 'Open Analytics', action: () => window.uiManager.switchView('analytics') },
      { id: 'toggle-theme', title: 'Toggle Dark/Light Theme', action: () => window.uiManager.toggleTheme() },
      { id: 'export-data', title: 'Export Backup JSON', action: () => window.exportEngine.exportJSON() },
      { id: 'import-data', title: 'Import Backup JSON', action: () => window.uiManager.openImportModal() },
      { id: 'undo', title: 'Undo Last Action', action: () => window.stateManager.undo() },
      { id: 'redo', title: 'Redo Action', action: () => window.stateManager.redo() },
      { id: 'settings', title: 'Open Settings', action: () => window.uiManager.switchView('settings') }
    ];
  }
}

window.commandPalette = new CommandPalette(window.stateManager);

/**
 * settings.js - Settings management and persistence.
 */
class SettingsManager {
  constructor(stateManager) {
    this.stateManager = stateManager;
  }

  updateSettings(newSettings) {
    this.stateManager.pushHistory();
    this.stateManager.state.settings = {
      ...this.stateManager.state.settings,
      ...newSettings
    };
    this.stateManager.persist();
    this.stateManager.logActivity('Updated settings');
    this.stateManager.notify();
    window.uiManager.applySettings();
  }
}

window.settingsManager = new SettingsManager(window.stateManager);

/**
 * notifications.js - Notification center management.
 */
class NotificationManager {
  constructor(stateManager) {
    this.stateManager = stateManager;
  }

  markAsRead(id) {
    const notif = this.stateManager.state.notifications.find(n => n.id === id);
    if (notif) {
      notif.read = true;
      this.stateManager.persist();
      this.stateManager.notify();
    }
  }

  markAllRead() {
    this.stateManager.state.notifications.forEach(n => n.read = true);
    this.stateManager.persist();
    this.stateManager.notify();
  }

  deleteNotification(id) {
    this.stateManager.state.notifications = this.stateManager.state.notifications.filter(n => n.id !== id);
    this.stateManager.persist();
    this.stateManager.notify();
  }
}

window.notificationManager = new NotificationManager(window.stateManager);

/**
 * import-export.js - JSON Export and Import with schema validation and merge/replace strategy.
 */
class ImportExportEngine {
  constructor(stateManager) {
    this.stateManager = stateManager;
  }

  exportJSON() {
    const data = {
      schemaVersion: 1,
      exportedAt: new Date().toISOString(),
      tasks: this.stateManager.state.tasks,
      projects: this.stateManager.state.projects,
      settings: this.stateManager.state.settings
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `nexus-titan-backup-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
    this.stateManager.addNotification('Export Successful', 'Full system backup exported successfully.', 'success');
  }

  importJSON(jsonString, strategy = 'merge') {
    try {
      const parsed = JSON.parse(jsonString);
      if (!parsed.schemaVersion || !Array.isArray(parsed.tasks) || !Array.isArray(parsed.projects)) {
        throw new Error('Invalid backup schema.');
      }

      this.stateManager.pushHistory();
      if (strategy === 'replace') {
        this.stateManager.state.tasks = parsed.tasks;
        this.stateManager.state.projects = parsed.projects;
        if (parsed.settings) this.stateManager.state.settings = parsed.settings;
      } else {
        // Merge strategy
        const existingTaskIds = new Set(this.stateManager.state.tasks.map(t => t.id));
        const existingProjIds = new Set(this.stateManager.state.projects.map(p => p.id));

        parsed.tasks.forEach(t => {
          if (!existingTaskIds.has(t.id)) {
            this.stateManager.state.tasks.push(t);
          }
        });

        parsed.projects.forEach(p => {
          if (!existingProjIds.has(p.id)) {
            this.stateManager.state.projects.push(p);
          }
        });
      }

      this.stateManager.persist();
      this.stateManager.logActivity('Imported data successfully');
      this.stateManager.addNotification('Import Successful', 'Data imported successfully.', 'success');
      this.stateManager.notify();
      return true;
    } catch (e) {
      this.stateManager.addNotification('Import Failed', e.message, 'error');
      throw e;
    }
  }
}

window.exportEngine = new ImportExportEngine(window.stateManager);

/**
 * worker.js - Web Worker for heavy dataset computations and analytics.
 */
self.onmessage = function(e) {
  const { type, tasks } = e.data;
  if (type === 'COMPUTE_ANALYTICS') {
    const total = tasks.length;
    const completed = tasks.filter(t => t.status === 'done').length;
    const completionRate = total > 0 ? Math.round((completed / total) * 100) : 0;

    self.postMessage({
      type: 'ANALYTICS_RESULT',
      result: { total, completed, completionRate }
    });
  }
};

const CACHE_NAME = 'nexus-titan-v1';
const ASSETS = [
  './index.html',
  './style.css',
  './app.js',
  './state.js',
  './storage.js',
  './tasks.js',
  './projects.js',
  './calendar.js',
  './analytics.js',
  './search.js',
  './commands.js',
  './settings.js',
  './notifications.js',
  './import-export.js'
];

self.addEventListener('install', (e) => {
  e.waitUntil(
    caches.open(CACHE_NAME).then(cache => cache.addAll(ASSETS)).catch(() => {})
  );
});

self.addEventListener('fetch', (e) => {
  e.respondWith(
    caches.match(e.request).then(response => response || fetch(e.request)).catch(() => caches.match('./index.html'))
  );
});

:root {
  --bg-primary: #0f172a;
  --bg-secondary: #1e293b;
  --bg-card: #1e293b;
  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --accent: #3b82f6;
  --border: #334155;
  --success: #22c55e;
  --warning: #f59e0b;
  --danger: #ef4444;
}

[data-theme="light"] {
  --bg-primary: #f8fafc;
  --bg-secondary: #ffffff;
  --bg-card: #ffffff;
  --text-primary: #0f172a;
  --text-secondary: #64748b;
  --accent: #2563eb;
  --border: #e2e8f0;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: system-ui, -apple-system, sans-serif; background-color: var(--bg-primary); color: var(--text-primary); line-height: 1.5; }

.app-container { display: flex; height: 100vh; overflow: hidden; }
.sidebar { width: 260px; background-color: var(--bg-secondary); border-right: 1px solid var(--border); display: flex; flex-direction: column; }
.sidebar-header { padding: 1.5rem; font-size: 1.25rem; font-weight: bold; border-bottom: 1px solid var(--border); }
.sidebar-nav { flex: 1; overflow-y: auto; padding: 1rem; }
.nav-item { display: block; padding: 0.75rem 1rem; color: var(--text-secondary); text-decoration: none; border-radius: 0.375rem; margin-bottom: 0.25rem; }
.nav-item:hover, .nav-item.active { background-color: var(--accent); color: white; }

.main-content { flex: 1; display: flex; flex-direction: column; overflow: hidden; }
.topbar { height: 64px; border-bottom: 1px solid var(--border); display: flex; align-items: center; justify-content: space-between; padding: 0 1.5rem; background-color: var(--bg-secondary); }
.content-view { flex: 1; overflow-y: auto; padding: 2rem; }

.card { background-color: var(--bg-card); border: 1px solid var(--border); border-radius: 0.5rem; padding: 1.5rem; margin-bottom: 1rem; }
.btn { background-color: var(--accent); color: white; border: none; padding: 0.5rem 1rem; border-radius: 0.375rem; cursor: pointer; }
.btn:hover { opacity: 0.9; }

.modal-overlay { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.5); display: flex; align-items: center; justify-content: center; z-index: 1000; }
.modal { background: var(--bg-secondary); border: 1px solid var(--border); border-radius: 0.5rem; padding: 2rem; width: 500px; max-width: 90%; }

.toast-container { position: fixed; bottom: 1rem; right: 1rem; z-index: 2000; }
.toast { background: var(--bg-secondary); border: 1px solid var(--border); padding: 1rem; border-radius: 0.375rem; margin-top: 0.5rem; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }

/**
 * app.js - Main Bootstrap, UI Coordinator, and Global Error Handling.
 */
class UIManager {
  constructor() {
    this.currentView = 'dashboard';
  }

  async init() {
    window.onerror = (msg, url, line) => {
      console.error('Global Error:', msg, url, line);
      this.showToast(`Error: ${msg}`, 'error');
    };

    window.addEventListener('unhandledrejection', event => {
      console.error('Unhandled Promise Rejection:', event.reason);
      this.showToast(`Error: ${event.reason.message || event.reason}`, 'error');
    });

    await window.storageEngine.init();
    await window.stateManager.loadState();

    window.stateManager.subscribe(() => this.render());
    this.setupListeners();
    this.render();

    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.register('service-worker.js').catch(() => {});
    }
  }

  setupListeners() {
    document.querySelectorAll('.sidebar-nav .nav-item').forEach(el => {
      el.addEventListener('click', (e) => {
        e.preventDefault();
        const view = el.getAttribute('data-view');
        this.switchView(view);
      });
    });

    window.addEventListener('keydown', (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault();
        window.commandPalette.toggle();
      }
      if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
        e.preventDefault();
        window.stateManager.undo();
      }
      if ((e.ctrlKey || e.metaKey) && e.key === 'y') {
        e.preventDefault();
        window.stateManager.redo();
      }
    });

    const btnQuickTask = document.getElementById('btn-quick-task');
    if (btnQuickTask) {
      btnQuickTask.addEventListener('click', () => {
        const title = prompt('Enter task title:');
        if (title) {
          window.taskEngine.createTask({ title });
        }
      });
    }
  }

  switchView(view) {
    this.currentView = view;
    document.querySelectorAll('.sidebar-nav .nav-item').forEach(el => {
      el.classList.toggle('active', el.getAttribute('data-view') === view);
    });
    document.getElementById('current-view-title').innerText = view.charAt(0).toUpperCase() + view.slice(1);
    this.render();
  }

  render() {
    const container = document.getElementById('main-view-container');
    if (!container) return;

    const metrics = window.analyticsEngine.computeMetrics();

    if (this.currentView === 'dashboard') {
      container.innerHTML = `
        <div style="display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; margin-bottom: 2rem;">
          <div class="card"><h3>Total Tasks</h3><p style="font-size:2rem; font-weight:bold;">${metrics.total}</p></div>
          <div class="card"><h3>Completed</h3><p style="font-size:2rem; font-weight:bold; color:var(--success);">${metrics.completed}</p></div>
          <div class="card"><h3>Overdue</h3><p style="font-size:2rem; font-weight:bold; color:var(--danger);">${metrics.overdue}</p></div>
          <div class="card"><h3>Completion Rate</h3><p style="font-size:2rem; font-weight:bold; color:var(--accent);">${metrics.completionRate}%</p></div>
        </div>
        <div class="card">
          <h3>Recent Activity</h3>
          <ul style="list-style:none; margin-top:1rem;">
            ${window.stateManager.state.activityLogs.slice(0, 5).map(log => `<li style="padding:0.5rem 0; border-bottom:1px solid var(--border);">${log.action} <span style="float:right; color:var(--text-secondary);">${new Date(log.timestamp).toLocaleTimeString()}</span></li>`).join('')}
          </ul>
        </div>
      `;
    } else if (this.currentView === 'tasks') {
      const tasks = window.stateManager.state.tasks;
      container.innerHTML = `
        <div class="card">
          <h3>Task Engine</h3>
          <table style="width:100%; border-collapse:collapse; margin-top:1rem;">
            <thead><tr style="text-align:left; border-bottom:1px solid var(--border);"><th style="padding:0.5rem;">Title</th><th>Status</th><th>Priority</th><th>Due Date</th><th>Actions</th></tr></thead>
            <tbody>
              ${tasks.map(t => `<tr style="border-bottom:1px solid var(--border);"><td style="padding:0.5rem;">${t.title}</td><td>${t.status}</td><td>${t.priority}</td><td>${t.dueDate || 'None'}</td><td><button class="btn" onclick="window.taskEngine.deleteTask('${t.id}')">Delete</button></td></tr>`).join('')}
            </tbody>
          </table>
        </div>
      `;
    } else if (this.currentView === 'developer') {
      container.innerHTML = `
        <div class="card">
          <h3>Developer Panel & Stress Test</h3>
          <p style="margin-top:1rem;">Generate bulk tasks for stress testing the search, filter, and analytics engines.</p>
          <div style="margin-top:1rem; display:flex; gap:1rem;">
            <button class="btn" onclick="window.uiManager.generateTasks(100)">Generate 100 Tasks</button>
            <button class="btn" onclick="window.uiManager.generateTasks(1000)">Generate 1,000 Tasks</button>
            <button class="btn" onclick="window.uiManager.generateTasks(5000)">Generate 5,000 Tasks</button>
            <button class="btn" style="background:var(--danger);" onclick="window.uiManager.clearDB()">Clear Database</button>
          </div>
        </div>
      `;
    } else {
      container.innerHTML = `<div class="card"><h3>${this.currentView.toUpperCase()}</h3><p>Module active and operational.</p></div>`;
    }
  }

  generateTasks(count) {
    for (let i = 0; i < count; i++) {
      window.stateManager.state.tasks.push({
        id: 'task_' + Math.random().toString(36).substr(2, 9),
        title: `Stress Test Task ${i + 1}`,
        description: 'Auto-generated for stress testing.',
        status: ['todo', 'in-progress', 'done'][Math.floor(Math.random() * 3)],
        priority: ['low', 'medium', 'high'][Math.floor(Math.random() * 3)],
        createdAt: new Date().toISOString(),
        dueDate: null
      });
    }
    window.stateManager.persist();
    window.stateManager.notify();
    this.showToast(`Successfully generated ${count} tasks.`, 'success');
  }

  clearDB() {
    if (confirm('Are you sure you want to clear all tasks?')) {
      window.stateManager.state.tasks = [];
      window.stateManager.persist();
      window.stateManager.notify();
      this.showToast('Database cleared.', 'info');
    }
  }

  showToast(message, type = 'info') {
    const container = document.getElementById('toast-container');
    if (!container) return;
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.innerText = message;
    container.appendChild(toast);
    setTimeout(() => toast.remove(), 3000);
  }

  toggleTheme() {
    const current = document.documentElement.getAttribute('data-theme');
    const next = current === 'light' ? 'dark' : 'light';
    if (next === 'light') {
      document.documentElement.setAttribute('data-theme', 'light');
    } else {
      document.documentElement.removeAttribute('data-theme');
    }
  }

  applySettings() {}
}

window.uiManager = new UIManager();
window.showToast = (msg, type) => window.uiManager.showToast(msg, type);
window.addEventListener('DOMContentLoaded', () => window.uiManager.init());
